use std::sync::Arc;

use axum::extract::{DefaultBodyLimit, State};
use axum::response::{IntoResponse, Response};
use axum::{Json, Router, http::StatusCode, routing::get, routing::post};
use serde_json::json;

use crate::adapters::iam::{Iam, IamError};
use crate::adapters::openai::OpenAiClient;
use crate::application::limits::Limits;

/// Deliberately-INVALID sentinel token for the `/readyz` IAM-reachability probe. It has no
/// `pgs_sk_` prefix, so a REACHABLE IAM parses and rejects it (an application-level `Status`, e.g.
/// `Unauthenticated`) while an UNREACHABLE IAM fails at the transport. It authenticates nothing —
/// the introspect is a cheap, unaudited parse-reject, never a real credential.
const READYZ_PROBE_TOKEN: &str = "readyz-probe";

/// Shared handler state: the IAM port (an `Arc<dyn Iam>` so tests inject a fake and the binary
/// injects the real `IamClient`), the OpenAI egress client, and the inbound body-size cap. `Clone`
/// is cheap (all fields are `Arc`/`Copy`), as axum requires for `State`.
#[derive(Clone)]
pub struct AppState {
    /// The IAM port the auth middleware queries (introspect + self-query authorize).
    pub iam: Arc<dyn Iam>,
    /// The outbound OpenAI egress client (holds the real key; forwards raw request bytes).
    pub openai: Arc<OpenAiClient>,
    /// Max inbound request-body size in bytes; an over-limit body is rejected by [`bytes::EnvelopeBytes`]
    /// with a `413` rendered inside the OpenAI envelope (SMA-588).
    pub max_request_bytes: usize,
    /// The capability toggles this build was configured with (SMA-505), projected once via
    /// `Capabilities::from_config` in `main.rs` (mirrors `paigasus-iam`'s `AppState.capabilities`
    /// — one source of truth, read by both the `chat` streaming guard and the `service_info`
    /// descriptor handler, rather than each holding/re-deriving its own bare bool).
    pub capabilities: crate::service_info::Capabilities,
use serde::{Deserialize, Serialize};

/// An OpenAI-compatible `POST /v1/chat/completions` request body, modelled just enough for the
/// gateway's needs. `model` and `messages` are the required core; `stream` selects the egress
/// path (defaults to `false` when absent); every other top-level field (`temperature`, `top_p`,
/// `tools`, `response_format`, …) is captured losslessly in [`extra`](Self::extra).
#[derive(Debug, Clone, Deserialize, Serialize)]
pub struct ChatCompletionRequest {
    /// The target model id (read for request logging; the upstream body carries it verbatim).
    pub model: String,
    /// Whether the caller requested a streamed (SSE) completion. Absent → `false`.
    #[serde(default)]
    pub stream: bool,
    /// The conversation turns, kept as opaque JSON. The gateway reads only the lengths of the
    /// message text, to estimate tokens. It never logs the content and never changes it.
    pub messages: Vec<serde_json::Value>,
    /// Every unmodelled top-level field, preserved verbatim so a round-trip is lossless.
    #[serde(flatten)]
    pub extra: serde_json::Map<String, serde_json::Value>,
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn parses_core_fields_and_captures_unknowns_in_extra() {
        // A realistic request carrying `model`/`stream`/`messages` plus several unmodelled
        // top-level fields — the exact shape a caller's OpenAI SDK emits.
        let raw = json!({
            "model": "gpt-4o-mini",
            "stream": true,
            "messages": [{ "role": "user", "content": "hi" }],
            "temperature": 0.7,
            "top_p": 0.9,
            "tools": [{ "type": "function", "function": { "name": "f" } }],
            "response_format": { "type": "json_object" }
        });

        let req: ChatCompletionRequest = serde_json::from_value(raw).expect("valid request parses");

        assert_eq!(req.model, "gpt-4o-mini");
        assert!(req.stream);
        assert_eq!(req.messages.len(), 1);

/// destructures the state by move, which a type with `Drop` forbids (E0509). When the stream ends,
/// fails, or is dropped, this value drops once, and the guard with it (SMA-677 § 4.6). The clean
/// end and the first error call `UsageScanner::finish()` first; a drop (client disconnect) does
/// not, so a last record with no blank line counts only when the upstream ended (SMA-730 D3).
struct Relay {
    phase: StreamState,
    scan: UsageScanner,
    guard: Option<ChargeGuard>,
}

/// One upstream chunk, read for billing before anything else sees it (SMA-677, SMA-749 D24).
/// Without a guard (no `[limits]`) nothing is parsed at all. Shared with the intercepting relay.
pub(crate) fn feed_scan(scan: &mut UsageScanner, guard: &mut Option<ChargeGuard>, chunk: &[u8]) {
    if let Some(guard) = guard.as_mut() {
        scan.feed(chunk);
        guard.set_stream_progress(scan.completion_records(), scan.reported_total());
    }
}

/// SMA-730: the upstream ended or failed. A last record with no blank line after it still
/// counts. Without a guard the scanner reads nothing, as in the chunk arm. Shared with the
/// intercepting relay (SMA-749 D24).
pub(crate) fn finish_scan(scan: &mut UsageScanner, guard: &mut Option<ChargeGuard>) {
    if let Some(guard) = guard.as_mut() {
        scan.finish();
        guard.set_stream_progress(scan.completion_records(), scan.reported_total());
    }
}

/// Adapt an [`OpenAiByteStream`] into a body stream that forwards each upstream chunk UNBUFFERED
/// and, on the FIRST upstream error, emits one terminal [`TERMINAL_SSE_ERROR`] event and ends.
///
/// Items are `Result<Bytes, Infallible>`: the outgoing stream never errors (a mid-stream upstream
/// failure becomes a data event, not a transport error), which keeps `Body::from_stream` from
/// aborting the response body. The inner stream is owned by the unfold state and dropped when this
/// stream is dropped — preserving reqwest's cancel-on-drop of the upstream request.
///
/// Runs with `paigasus_observability::current_ids() == None` (SMA-504 spec §4.3, situation 3):
/// this function is polled by hyper after the request-head future — the one the
/// `CorrelationLayer` task-local scope covers — has already resolved. See the call site's
/// comment in `chat_completions`.

